package com.thang.user.service.user;
import com.thang.user.model.entity.*;import com.thang.user.model.dto.MessageResponseUser;import com.thang.user.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import org.springframework.scheduling.annotation.Scheduled;import java.time.*;import java.util.*;import java.security.*;
@Service @RequiredArgsConstructor
public class AccountRecoveryService {
 private final IUserRepository users;private final PasswordRecoveryRepository recovery;private final PasswordEncoder passwords;private final SessionService sessions;private final ActivationOutboxService mail;
 private final RateLimitService limits;
 public record Reset(String id,String token,String password,String confirmPassword){}
 @Transactional public void request(String email){if(email==null||email.length()>255||!email.trim().matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))return;var reference=users.findByEmail(email.trim()).orElse(null);var user=reference==null?null:users.lockById(reference.getUserId()).orElse(null);if(user==null||!user.isActive()||recovery.existsByUserIdAndCreatedAtGreaterThan(user.getUserId(),System.currentTimeMillis()-60000))return;if(!limits.consume(new RateLimitService.Limit("PASSWORD_RECOVERY_ACCOUNT",user.getUserId())).allowed())return;byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);var row=new PasswordRecovery();row.setId(UUID.randomUUID().toString());row.setUserId(user.getUserId());row.setTokenHash(PasswordSetupService.hash(token));row.setCredentialFingerprint(PasswordSetupService.hash(user.getPassword()==null?"":user.getPassword()));row.setCreatedAt(System.currentTimeMillis());row.setExpiresAt(row.getCreatedAt()+900000);recovery.invalidate(user.getUserId(),row.getCreatedAt());recovery.save(row);var message=new MessageResponseUser();message.setToUserId(user.getUserId());message.setToUserEmail(user.getEmail());message.setToUserFullName((user.getFirstName()+" "+user.getLastName()).trim());message.setPurpose("PASSWORD_RESET");message.setRecoveryId(row.getId());message.setRecoveryToken(token);mail.enqueue(message,LocalDateTime.ofInstant(Instant.ofEpochMilli(row.getExpiresAt()),ZoneId.systemDefault()));}
 @Transactional public void reset(Reset input){if(input==null||input.id()==null||input.token()==null||input.token().length()>100||!PasswordPolicy.valid(input.password())||!input.password().equals(input.confirmPassword()))throw invalid();var reference=recovery.findById(input.id()).orElseThrow(AccountRecoveryService::invalid);var user=users.lockById(reference.getUserId()).orElseThrow(AccountRecoveryService::invalid);var row=recovery.lock(input.id()).orElseThrow(AccountRecoveryService::invalid);if(!user.isActive()||row.getUsedAt()!=0||row.getExpiresAt()<System.currentTimeMillis()||!row.getCredentialFingerprint().equals(PasswordSetupService.hash(user.getPassword()==null?"":user.getPassword()))||!MessageDigest.isEqual(row.getTokenHash().getBytes(java.nio.charset.StandardCharsets.US_ASCII),PasswordSetupService.hash(input.token()).getBytes(java.nio.charset.StandardCharsets.US_ASCII)))throw invalid();user.setPassword(passwords.encode(input.password()));user.setPasswordSetupHash(null);user.setPasswordSetupExpiresAt(null);user.setDateModified(LocalDateTime.now());recovery.invalidate(user.getUserId(),System.currentTimeMillis());sessions.removeSession(user.getUserId());}
 @Scheduled(fixedDelay=86400000) @Transactional public void cleanup(){recovery.cleanup(System.currentTimeMillis()-86400000);}
 private static ResponseStatusException invalid(){return new ResponseStatusException(HttpStatus.BAD_REQUEST,"Liên kết không hợp lệ/đã hết hạn hoặc mật khẩu chưa đáp ứng yêu cầu");}
}
